-- 回滚：dailyhot 侧 50 个源恢复启用，对应 custom 源停用
-- ⚠️ 用 enabled=false 而不是 DELETE：custom 源已入库 items 有外键，删除会级联清掉历史（只停增量、不删历史）
BEGIN;
UPDATE sources SET enabled=true, updated_at=now() WHERE engine='dailyhot' AND src_id IN ('36kr', '51cto', '52pojie', 'acfun', 'baidu', 'bilibili', 'csdn', 'dgtle', 'douban-group', 'douban-movie', 'douyin', 'geekpark', 'genshin', 'github', 'guokr', 'hackernews', 'hellogithub', 'history', 'honkai', 'hupu', 'huxiu', 'ifanr', 'ithome', 'ithome-xijiayi', 'jianshu', 'juejin', 'kuaishou', 'lol', 'miyoushe', 'netease-news', 'newsmth', 'ngabbs', 'nodeseek', 'nytimes', 'qq-news', 'sina', 'sina-news', 'smzdm', 'sspai', 'starrail', 'thepaper', 'tieba', 'toutiao', 'v2ex', 'weatheralarm', 'weibo', 'weread', 'yystv', 'zhihu', 'zhihu-daily');
